{| class="vertical-navbox {{#if:{{{wraplinks|}}}|{{#ifeq: {{{wraplinks|}}}|true||nowraplinks}}|nowraplinks}} {{{class|}}} {{{bodyclass|}}}" cellspacing="5" style="float: right; clear: right; color: black; background: #f9f9f9; border: 1px solid #aaa; width: 22em; margin: 0 0 1.0em 1.0em; padding: 0.2em; border-spacing: 0.4em 0; text-align: center; line-height: 1.4em; font-size: 88%; {{{style|}}} {{{bodystyle|}}}" cellpadding="{{{cellpadding|0}}}"
{{#if:{{{outertitle<includeonly>|</includeonly>}}}|
{{!}}+ class="{{{outertitleclass|}}}" style="padding-bottom: 0.2em; font-size: 125%; line-height: 1.15em; font-weight: bold; {{{outertitlestyle|}}}" {{!}} {{{outertitle}}}
}}
{{#if:{{{topimage<includeonly>|</includeonly>}}}|
{{!}} class="{{{topimageclass|}}}" style="padding: 0.4em 0; {{{topimagestyle|}}}" {{!}} {{{topimage}}} {{#if:{{{topcaption<includeonly>|</includeonly>}}}|<div style="padding-top: 0.2em; font-size: 85%; line-height: 1.2em; {{{topcaptionstyle|}}}">{{{topcaption}}}</div>}}
{{!}}-
}}
{{#if:{{{pretitle<includeonly>|</includeonly>}}}|
{{!}} class="{{{pretitleclass|}}}" style="{{#if:{{{topimage<includeonly>|</includeonly>}}}|padding-top: 0.2em; |padding-top: 0.4em;}} font-size: 85%; line-height: 1.2em; {{{pretitlestyle|}}}" {{!}} {{{pretitle}}}
{{!}}-
}}
{{#if:{{{title<includeonly>|</includeonly>}}}|
! class="{{{titleclass|}}}" style="padding: 0.2em 0.4em 0.2em; {{#if:{{{pretitle<includeonly>|</includeonly>}}}|padding-top: 0;}} font-size: 145%; line-height: 1.15em; font-weight: bold; {{{titlestyle|}}}" {{!}} {{{title}}}
{{!}}-
}}
{{#if:{{{image<includeonly>|</includeonly>}}}|
{{!}} class="{{{imageclass|}}}" style="padding: 0.2em 0 0.4em; {{{imagestyle|}}}" {{!}} {{{image}}}{{#if:{{{caption<includeonly>|</includeonly>}}}|
